import React from 'react';
import '../styles/getinvolved.css';

function GetInvolved() {
  return (
    <div className="involved">
      <h2>Get Involved</h2>
      <p>Support our mission by volunteering, partnering, or donating to WE4HIM.</p>
    </div>
  );
}

export default GetInvolved;
